 * @example
 * image.filters([Konva.Filters.HSV]);
 * image.value(1); // twice as bright
 */
export const HSV = function (imageData) {
  const data = imageData.data,
    nPixels = data.length,
    v = Math.pow(2, this.value()),
    s = Math.pow(2, this.saturation()),
    h = (this.hue() % 360 + 360) % 360;
